using System.Text.Json;
using OcctSharp.ConfiguredMeshExchange;
using OcctSharp.DocumentProjections;
using OcctSharp.Tests.Shared;
using OcctSharp.XdeMetadataWorkspaces;
using OcctSharp.MeshingWorkspaces;
namespace OcctSharp.Runtime.Tests;
public sealed class ConfiguredMeshTests {
 static readonly int[] ExpectedResourceMapping=[0,0,1];
 [Fact]public void CanonicalResourceSharingRequiresExactRecordsAndPreservesDistinctNames(){string root=DirectoryName();try{string path=Path.Combine(root,"resources.gltf");string mesh="{\"name\":\"part\",\"primitives\":[{\"attributes\":{\"POSITION\":0},\"indices\":1}]}";File.WriteAllText(path,"{\"asset\":{\"version\":\"2.0\"},\"buffers\":[{\"byteLength\":42,\"uri\":\"data.bin\"}],\"bufferViews\":[{\"buffer\":0,\"byteLength\":36},{\"buffer\":0,\"byteOffset\":36,\"byteLength\":6}],\"accessors\":[{\"count\":3,\"bufferView\":0,\"componentType\":5126,\"type\":\"VEC3\"},{\"count\":3,\"bufferView\":1,\"componentType\":5123,\"type\":\"SCALAR\"}],\"meshes\":["+mesh+","+mesh+","+mesh.Replace("part","other",StringComparison.Ordinal)+"],\"nodes\":[{\"mesh\":0},{\"mesh\":1},{\"mesh\":2}]}");typeof(ConfiguredMeshFiles).GetMethod("CanonicalMeshes",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static)!.Invoke(null,[path]);using var json=JsonDocument.Parse(File.ReadAllBytes(path));Assert.Equal(2,json.RootElement.GetProperty("meshes").GetArrayLength());Assert.Equal(ExpectedResourceMapping,json.RootElement.GetProperty("nodes").EnumerateArray().Select(x=>x.GetProperty("mesh").GetInt32()));Assert.Equal("other",json.RootElement.GetProperty("meshes")[1].GetProperty("name").GetString());}finally{Directory.Delete(root,true);}}
 [Fact]public void ActualWireNormalsAndRotatedOccurrenceReadbackUseOneCoordinateConversion(){string root=DirectoryName();try{using var assembly=BatchBKConfiguredMeshWorkflow.Assembly();using var context=DocumentProjectionContext.Bind(assembly.Document!);BatchBKConfiguredMeshWorkflow.MeshDefinitions(assembly,context);string path=Path.Combine(root,"original.gltf");ConfiguredMeshFiles.WriteNew(context,path,ConfiguredMeshFormat.Gltf,BatchBKConfiguredMeshWorkflow.ToGltf);BatchBKWireChecks.Check(path);var json=System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(path))!.AsObject();var nodes=json["nodes"]!.AsArray();var translated=nodes.Select(x=>x!.AsObject()).Single(x=>x["translation"] is System.Text.Json.Nodes.JsonArray translation&&Math.Abs(translation[0]!.GetValue<double>()-.01)<1e-6);translated["rotation"]=new System.Text.Json.Nodes.JsonArray(0,Math.Sqrt(.5),0,Math.Sqrt(.5));string rotated=Path.Combine(root,"rotated.gltf");File.WriteAllText(rotated,json.ToJsonString());using var read=ConfiguredMeshFiles.Read(rotated,ConfiguredMeshFormat.Gltf,BatchBKConfiguredMeshWorkflow.FromGltf);var mesh=MeshTopology.SnapshotExisting(read.Shape).Mesh;Assert.Equal(10,mesh.Positions.Max(p=>p.X)-mesh.Positions.Min(p=>p.X),4);Assert.Equal(3,mesh.Positions.Max(p=>p.Y)-mesh.Positions.Min(p=>p.Y),4);Assert.Equal(4,mesh.Positions.Max(p=>p.Z)-mesh.Positions.Min(p=>p.Z),4);Assert.All(mesh.Normals??throw new InvalidOperationException("Missing imported native normal channel."),normal=>Assert.Equal(1,Math.Sqrt(normal.X*normal.X+normal.Y*normal.Y+normal.Z*normal.Z),4));}finally{Directory.Delete(root,true);}}
 static string DirectoryName(){string root=Path.Combine(Path.GetTempPath(),"BK-tests-"+Guid.NewGuid());Directory.CreateDirectory(root);return root;}
 [Fact]public void WholeRoundActualAssemblyUnitMaterialMeshAndVisibleSourceChain()=>BatchBKConfiguredMeshWorkflow.Run();
 [Theory][InlineData(0)][InlineData(-1)][InlineData(double.NaN)][InlineData(double.PositiveInfinity)]
 public void InvalidUnitsFailBeforeExport(double unit){using var assembly=BatchBKConfiguredMeshWorkflow.Assembly();using var context=DocumentProjectionContext.Bind(assembly.Document!);Assert.Throws<ArgumentOutOfRangeException>(()=>ConfiguredMeshFiles.WriteNew(context,"bad.gltf",ConfiguredMeshFormat.Gltf,new(unit,MeshUpAxis.Z,1,MeshUpAxis.Y)));}
 [Fact]public void GltfWireCoordinatesAreRequiredForReadAndWrite(){using var assembly=BatchBKConfiguredMeshWorkflow.Assembly();using var context=DocumentProjectionContext.Bind(assembly.Document!);Assert.Throws<ArgumentException>(()=>ConfiguredMeshFiles.WriteNew(context,"bad.gltf",ConfiguredMeshFormat.Gltf,new(.001,MeshUpAxis.Z,.001,MeshUpAxis.Z)));Assert.Throws<ArgumentException>(()=>ConfiguredMeshFiles.Read("absent.gltf",ConfiguredMeshFormat.Gltf,new(.001,MeshUpAxis.Z,.001,MeshUpAxis.Z)));}
 [Fact]public void CommonChangesRequireCommandPreservePbrAndRestoreThroughHistory(){using var assembly=BatchBKConfiguredMeshWorkflow.Assembly();using var context=DocumentProjectionContext.Bind(assembly.Document!);using var metadata=XdeMetadataContext.Bind(context);assembly.Document!.NewCommand();var label=metadata.CreateMaterial("common",new(.2,.3,.4,1),.4,.7,[context.GetLabel(assembly.Occurrences[0].DefinitionEntry)]);Assert.True(assembly.Document.CommitCommand());Assert.Null(ConfiguredMeshFiles.ReadCommon(context,label)?.Values);Assert.ThrowsAny<Exception>(()=>ConfiguredMeshFiles.ReplaceCommon(context,label,BatchBKConfiguredMeshWorkflow.Common));assembly.Document.NewCommand();ConfiguredMeshFiles.ReplaceCommon(context,label,BatchBKConfiguredMeshWorkflow.Common);assembly.Document.AbortCommand();Assert.Null(ConfiguredMeshFiles.ReadCommon(context,label)?.Values);assembly.Document.NewCommand();ConfiguredMeshFiles.ReplaceCommon(context,label,BatchBKConfiguredMeshWorkflow.Common);Assert.True(assembly.Document.CommitCommand());Assert.NotNull(ConfiguredMeshFiles.ReadCommon(context,label)?.Values);Assert.Equal(.4,metadata.Snapshot().Materials.Single(x=>x.Entry==label.Entry).Pbr!.Metallic,6);Assert.True(assembly.Document.Undo());Assert.Null(ConfiguredMeshFiles.ReadCommon(context,label)?.Values);Assert.True(assembly.Document.Redo());Assert.NotNull(ConfiguredMeshFiles.ReadCommon(context,label)?.Values);}
 [Fact]public void ForeignLabelsAndClosedParentsFailBeforeNativeMaterialMutation(){using var first=BatchBKConfiguredMeshWorkflow.Assembly();using var second=BatchBKConfiguredMeshWorkflow.Assembly();using var a=DocumentProjectionContext.Bind(first.Document!);using var b=DocumentProjectionContext.Bind(second.Document!);Assert.Throws<ArgumentException>(()=>ConfiguredMeshFiles.ReadCommon(a,b.GetLabel(second.FreeRoots[0].Entry)));var label=a.GetLabel(first.FreeRoots[0].Entry);first.Dispose();Assert.Throws<ObjectDisposedException>(()=>ConfiguredMeshFiles.ReadCommon(a,label));}
 [Fact]public void DefinitionReplacementRejectsOccurrencesAndRestoresUnmeshedGeometryThroughHistory(){using var assembly=BatchBKConfiguredMeshWorkflow.Assembly();using var context=DocumentProjectionContext.Bind(assembly.Document!);using var initial=assembly.CopyOccurrence(1);using var mesh=ControlledMeshing.Run(initial,new(Deflection:.05));using var copied=mesh.CopyShape();var occurrence=context.GetLabel(assembly.Occurrences[0].Entry);var definition=context.GetLabel(assembly.Occurrences[0].DefinitionEntry);Assert.ThrowsAny<Exception>(()=>ConfiguredMeshFiles.ReplaceTriangulatedDefinition(context,definition,copied));assembly.Document!.NewCommand();Assert.ThrowsAny<Exception>(()=>ConfiguredMeshFiles.ReplaceTriangulatedDefinition(context,occurrence,copied));ConfiguredMeshFiles.ReplaceTriangulatedDefinition(context,definition,copied);assembly.Document.AbortCommand();assembly.Document.NewCommand();ConfiguredMeshFiles.ReplaceTriangulatedDefinition(context,definition,copied);Assert.True(assembly.Document.CommitCommand());using(var first=assembly.CopyOccurrence(1))Assert.True(MeshTopology.SnapshotExisting(first).Mesh.Triangles.Count>0);Assert.True(assembly.Document.Undo());Assert.True(assembly.Document.Redo());using(var second=assembly.CopyOccurrence(2))Assert.True(MeshTopology.SnapshotExisting(second).Mesh.Triangles.Count>0);Assert.Equal(2,assembly.Occurrences.Count);}
 [Fact]public void MissingTriangulationAndOpenCommandsCannotPublishMeshFiles(){string root=DirectoryName();try{using var assembly=BatchBKConfiguredMeshWorkflow.Assembly();using var context=DocumentProjectionContext.Bind(assembly.Document!);string path=Path.Combine(root,"missing.gltf");Assert.ThrowsAny<Exception>(()=>ConfiguredMeshFiles.WriteNew(context,path,ConfiguredMeshFormat.Gltf,BatchBKConfiguredMeshWorkflow.ToGltf));Assert.Empty(Directory.GetFiles(root));BatchBKConfiguredMeshWorkflow.MeshDefinitions(assembly,context);assembly.Document!.NewCommand();Assert.ThrowsAny<Exception>(()=>ConfiguredMeshFiles.WriteNew(context,path,ConfiguredMeshFormat.Gltf,BatchBKConfiguredMeshWorkflow.ToGltf));assembly.Document.AbortCommand();Assert.Empty(Directory.GetFiles(root));}finally{Directory.Delete(root,true);}}
 [Fact]public void ExistingOutputsAndInvalidMetadataArePreservedWithoutPartialPublication(){string root=DirectoryName();try{using var assembly=BatchBKConfiguredMeshWorkflow.Assembly();using var context=DocumentProjectionContext.Bind(assembly.Document!);BatchBKConfiguredMeshWorkflow.MeshDefinitions(assembly,context);string path=Path.Combine(root,"assembly.gltf");File.WriteAllText(path,"keep");Assert.Throws<IOException>(()=>ConfiguredMeshFiles.WriteNew(context,path,ConfiguredMeshFormat.Gltf,BatchBKConfiguredMeshWorkflow.ToGltf));Assert.Equal("keep",File.ReadAllText(path));Assert.Single(Directory.GetFiles(root));Assert.Throws<ArgumentException>(()=>ConfiguredMeshFiles.WriteNew(context,Path.Combine(root,"another.gltf"),ConfiguredMeshFormat.Gltf,BatchBKConfiguredMeshWorkflow.ToGltf,metadata:[new("key","a"),new("key","b")]));Assert.Single(Directory.GetFiles(root));}finally{Directory.Delete(root,true);}}
 [Theory][InlineData("../outside.bin")][InlineData("NUL.bin")][InlineData("https://example.invalid/data.bin")][InlineData("encoded%2e.bin")]
 public void GltfExternalUriMustBeAnExactFlatUnencodedName(string name){string root=DirectoryName();try{string path=Path.Combine(root,"bad.gltf");File.WriteAllText(path,JsonSerializer.Serialize(new{asset=new{version="2.0"},buffers=new[]{new{byteLength=4,uri=name}}}));Assert.ThrowsAny<ArgumentException>(()=>ConfiguredMeshFiles.Read(path,ConfiguredMeshFormat.Gltf,BatchBKConfiguredMeshWorkflow.FromGltf));}finally{Directory.Delete(root,true);}}
 [Theory][InlineData("cycle")][InlineData("index")][InlineData("accessor")][InlineData("texture")][InlineData("compression")]
 public void MalformedGraphOrDeferredContentFailsBeforeNativeRead(string kind){string root=DirectoryName();try{string path=Path.Combine(root,"bad.gltf");string extra=kind switch{"cycle"=>"\"nodes\":[{\"children\":[1]},{\"children\":[0]}]","index"=>"\"nodes\":[{\"children\":[2]}]","accessor"=>"\"accessors\":[{\"count\":4194305}]","texture"=>"\"images\":[{}]",_=>"\"extensionsUsed\":[\"KHR_draco_mesh_compression\"]"};File.WriteAllText(path,"{\"asset\":{\"version\":\"2.0\"},"+extra+"}");Assert.ThrowsAny<Exception>(()=>ConfiguredMeshFiles.Read(path,ConfiguredMeshFormat.Gltf,BatchBKConfiguredMeshWorkflow.FromGltf));}finally{Directory.Delete(root,true);}}
 [Fact]public void MissingExternalBuffersAndLazyMetadataBudgetsStopBeforePublication(){string root=DirectoryName();try{string path=Path.Combine(root,"missing.gltf");File.WriteAllText(path,"{\"asset\":{\"version\":\"2.0\"},\"buffers\":[{\"byteLength\":4,\"uri\":\"missing.bin\"}]}");Assert.ThrowsAny<IOException>(()=>ConfiguredMeshFiles.Read(path,ConfiguredMeshFormat.Gltf,BatchBKConfiguredMeshWorkflow.FromGltf));using var assembly=BatchBKConfiguredMeshWorkflow.Assembly();using var context=DocumentProjectionContext.Bind(assembly.Document!);int seen=0;IEnumerable<KeyValuePair<string,string>> Rows(){while(true){++seen;yield return new("key","value");}}Assert.Throws<ArgumentOutOfRangeException>(()=>ConfiguredMeshFiles.WriteNew(context,Path.Combine(root,"out.gltf"),ConfiguredMeshFormat.Gltf,BatchBKConfiguredMeshWorkflow.ToGltf,metadata:Rows()));Assert.Equal(4097,seen);Assert.Single(Directory.GetFiles(root));}finally{Directory.Delete(root,true);}}
}
